import sys, heapq
lines = sys.stdin.read().splitlines()
if lines:
    n = int(lines[0])
    pts = []
    for line in lines[1:1+n]:
        xy = [int(v) for v in line.split()]
        if len(xy) == 2: pts.append(xy)
    if n <= 1: print(0); sys.exit(0)
    visited = [False] * n
    min_d = [float('inf')] * n
    min_d[0] = 0
    total_cost = 0
    pq = [(0, 0)]
    while pq:
        cost, u = heapq.heappop(pq)
        if visited[u]: continue
        visited[u] = True
        total_cost += cost
        for v in range(n):
            if not visited[v]:
                d = abs(pts[u][0] - pts[v][0]) + abs(pts[u][1] - pts[v][1])
                if d < min_d[v]:
                    min_d[v] = d
                    heapq.heappush(pq, (d, v))
    print(total_cost)
